begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.k(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.k(n),'attention-'||n||'@example.test','{}' from generate_series(1,4)n;
insert into public.organizations(id,name,created_by) values(pg_temp.k(10),'Attention Alpha',pg_temp.k(1)),(pg_temp.k(11),'Attention Beta',pg_temp.k(4));
insert into public.memberships(organization_id,user_id,role) values(pg_temp.k(10),pg_temp.k(1),'OWNER'),(pg_temp.k(10),pg_temp.k(2),'MEMBER'),(pg_temp.k(10),pg_temp.k(3),'VIEWER'),(pg_temp.k(11),pg_temp.k(4),'OWNER');
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
insert into public.tasks(id,organization_id,title,assignee_id,due_at,priority,created_by,updated_by) values
(pg_temp.k(20),pg_temp.k(10),'Overdue assigned',pg_temp.k(1),now()-interval '1 day','HIGH',pg_temp.k(1),pg_temp.k(1)),
(pg_temp.k(21),pg_temp.k(10),'Blocked team work',pg_temp.k(2),null,'HIGH',pg_temp.k(1),pg_temp.k(1)),
(pg_temp.k(22),pg_temp.k(10),'Unfinished prerequisite',null,null,'LOW',pg_temp.k(1),pg_temp.k(1));
set local role authenticated;
select public.set_task_dependency(pg_temp.k(10),pg_temp.k(21),pg_temp.k(22),true);
select public.save_milestone(pg_temp.k(10),pg_temp.k(30),'Delivery tomorrow','',current_date+1,'ACTIVE',pg_temp.k(1),false,null);
select ok(public.daily_core_attention(pg_temp.k(10),now()) @> '[{"title":"Overdue assigned","scope":"personal","reason":"Overdue"}]','overdue assigned Task is personal attention');
select ok(public.daily_core_attention(pg_temp.k(10),now()) @> '[{"title":"Blocked team work","scope":"team","reason":"Blocked by unfinished work"}]','important blocked work surfaces for the team');
select ok(public.daily_core_attention(pg_temp.k(10),now()) @> '[{"title":"Delivery tomorrow","kind":"milestone"}]','real approaching Milestone surfaces');
select ok(not public.daily_core_attention(pg_temp.k(10),now()) @> '[{"title":"Unfinished prerequisite"}]','unassigned low-priority undated work is not a vanity count');
select throws_ok($$select public.daily_core_attention(pg_temp.k(11),now())$$,'42501',null,'foreign daily work is denied');
select throws_ok($$select public.daily_core_attention(pg_temp.k(10),null)$$,'22023',null,'time boundary is explicit');
select throws_ok($$select public.marketing_daily_attention(pg_temp.k(10),now())$$,'42501',null,'disabled Marketing is denied at the data boundary');
select public.set_organization_plugin_enabled(pg_temp.k(10),'marketing',true);
select public.save_marketing_hypothesis(pg_temp.k(10),pg_temp.k(40),jsonb_build_object('title','Untested strong belief','statement','A concrete testable belief about setup','status','READY_TO_TEST','confidence','HIGH','ownerId',pg_temp.k(2)),null);
select ok(public.marketing_daily_attention(pg_temp.k(10),now()) @> '[{"title":"Untested strong belief","kind":"hypothesis","scope":"team"}]','recorded high confidence without a test surfaces honestly');
select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(50),jsonb_build_object('title','Setup comparison','hypothesisId',pg_temp.k(40),'testPlan','Compare two onboarding messages','successCriteria','Seven of ten finish independently','ownerId',pg_temp.k(1),'endsOn',current_date+1),null);
select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(50),jsonb_build_object('title','Setup comparison','hypothesisId',pg_temp.k(40),'testPlan','Compare two onboarding messages','successCriteria','Seven of ten finish independently','ownerId',pg_temp.k(1),'endsOn',current_date+1,'status','RUNNING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(50)));
select ok(public.marketing_daily_attention(pg_temp.k(10),now()) @> '[{"title":"Setup comparison","scope":"personal","reason":"Experiment ending soon"}]','assigned running Experiment with recorded end date surfaces');
select ok(not public.marketing_daily_attention(pg_temp.k(10),now()) @> '[{"kind":"hypothesis"}]','a belief with an existing test is not called untested');
select public.save_marketing_experiment(pg_temp.k(10),pg_temp.k(50),jsonb_build_object('title','Setup comparison','hypothesisId',pg_temp.k(40),'testPlan','Compare two onboarding messages','successCriteria','Seven of ten finish independently','ownerId',pg_temp.k(1),'endsOn',current_date+1,'status','EVALUATING'),(select updated_at from public.marketing_experiments where id=pg_temp.k(50)));
select ok(public.marketing_daily_attention(pg_temp.k(10),now()) @> '[{"title":"Setup comparison","reason":"Ready for evaluation"}]','evaluation is its own actionable reason');
select public.evaluate_marketing_experiment(pg_temp.k(10),pg_temp.k(50),'INCONCLUSIVE','The sample was too small to decide',(select updated_at from public.marketing_experiments where id=pg_temp.k(50)),null,false);
select public.save_marketing_learning(pg_temp.k(10),pg_temp.k(60),pg_temp.k(50),'Need a broader sample','Repeat with a broader sample before changing positioning','LOW');
select ok(public.marketing_daily_attention(pg_temp.k(10),now()) @> '[{"title":"Need a broader sample","kind":"learning"}]','recent recorded Learning is inspectable');
select is((select count(*)::integer from public.knowledge_memories),0,'attention and execution never automatically promote Memory');
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select lives_ok($$select public.daily_core_attention(pg_temp.k(10),now())$$,'VIEWER can inspect daily work');
select lives_ok($$select public.marketing_daily_attention(pg_temp.k(10),now())$$,'VIEWER can inspect enabled Marketing attention');
select throws_ok($$select public.marketing_daily_attention(pg_temp.k(11),now())$$,'42501',null,'no foreign Marketing attention titles');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
insert into public.tasks(id,organization_id,title,assignee_id,due_at,created_by,updated_by) select pg_temp.k(100+n),pg_temp.k(10),'Bounded assigned '||n,pg_temp.k(1),now()-interval '2 days',pg_temp.k(1),pg_temp.k(1) from generate_series(1,30)n;
set local role authenticated;
select is((select count(*)::integer from jsonb_array_elements(public.daily_core_attention(pg_temp.k(10),now())) v where v->>'kind'='task' and v->>'scope'='personal'),6,'personal Task projection remains bounded');
reset role;
update public.memberships set removed_at=now() where organization_id=pg_temp.k(10) and user_id=pg_temp.k(3);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select throws_ok($$select public.daily_core_attention(pg_temp.k(10),now())$$,'42501',null,'membership revocation takes effect on new Core reads');
select throws_ok($$select public.marketing_daily_attention(pg_temp.k(10),now())$$,'42501',null,'membership revocation takes effect on plugin reads');
select * from finish();
rollback;
